create function pg_temp.ok(b boolean,label text) returns void language plpgsql as $$begin if b is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.fails(q text,expected text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then if position(expected in sqlerrm)=0 then raise exception 'Unexpected [%] for %',sqlerrm,label;end if;raise notice 'PASS %',label;return;end;raise exception 'FAIL expected rejection %',label;end$$;
select id as asst from roles where code='ASISTENTE_OPERACIONES' \gset
select id as super from roles where code='SUPER_USUARIO' \gset
select id as lab from roles where code='LABORATORIO' \gset
set role authenticated;select set_config('test.actor','e2000000-0000-0000-0000-000000000001',false);
select pg_temp.ok((select count(*)=62 and bool_and(enabled) from vw_my_module_access),'super has every module');
select pg_temp.fails(format('update role_module_access set enabled=false where role_id=%L and route_key=''donors''',:'super'),'conserva acceso total','super cannot lose module access');
select pg_temp.fails(format('update role_module_access set enabled=true where role_id=%L and route_key=''users''',:'asst'),'exclusiva del Super','identity administration remains exclusive');
select pg_temp.fails(format('update role_module_access set role_id=%L where role_id=%L',:'lab',:'asst'),'permission denied','role identity cannot be reassigned');
select pg_temp.fails('delete from role_module_access','permission denied','activation settings cannot be deleted');
select set_config('test.actor','e2000000-0000-0000-0000-000000000002',false);
select pg_temp.ok((select enabled from vw_my_module_access where route_key='donors'),'operations can open donor workspace');
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='screening'),'operations has no laboratory window');
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='collections'),'operations has no financial collection window');
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='users'),'operations has no identity administration');
select pg_temp.ok((select count(*)=62 from role_module_access),'user reads only own role configuration');
select pg_temp.fails(format('select set_role_modules(%L,''[]'')',:'asst'),'Solo el Super','operator cannot configure windows');
update role_module_access set enabled=true where role_id=:'asst' and route_key='screening';
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='screening'),'direct operator update cannot bypass RLS');
select set_config('test.actor','e2000000-0000-0000-0000-000000000006',false);
select pg_temp.fails(format('select set_role_modules(%L,''[]'')',:'asst'),'Solo el Super','administrator cannot impersonate super');
select set_config('test.actor','e2000000-0000-0000-0000-000000000001',false);
select set_role_modules(:'asst',jsonb_build_array(jsonb_build_object('route_key','donors','enabled',false,'revision',1)));
select pg_temp.ok((select count(*)=1 from role_module_changes),'module changes are audited');
select pg_temp.fails(format('select set_role_modules(%L,%L)',:'asst','[{"route_key":"donors","enabled":true,"revision":1}]'),'configuración cambió','stale settings are rejected');
select pg_temp.fails(format('select set_role_modules(%L,%L)',:'asst','[{"route_key":"commercial","enabled":false,"revision":1},{"route_key":"donors","enabled":true,"revision":1}]'),'configuración cambió','batch conflict rejects entire save');
select pg_temp.ok((select enabled and revision=1 from role_module_access where role_id=:'asst' and route_key='commercial'),'failed batch preserves earlier settings');
select pg_temp.ok((select count(*)=1 from role_module_changes),'failed batch rolls audit back');
select set_config('test.actor','e2000000-0000-0000-0000-000000000002',false);
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='donors'),'deactivation takes effect on next server read');
select pg_temp.ok(has_permission('DONORS_VIEW'),'deactivation does not rewrite data permissions');
select set_config('test.actor','e2000000-0000-0000-0000-000000000004',false);
select pg_temp.ok((select enabled from vw_my_module_access where route_key='screening'),'laboratory retains screening');
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='sales'),'laboratory cannot gain financial window without permission');
select set_config('test.actor','e2000000-0000-0000-0000-000000000001',false);
select set_role_modules(:'asst',jsonb_build_array(jsonb_build_object('route_key','sales','enabled',false,'revision',1)));
select set_role_modules(:'lab',jsonb_build_array(jsonb_build_object('route_key','sales','enabled',true,'revision',1)));
select set_config('test.actor','e2000000-0000-0000-0000-000000000004',false);
select pg_temp.ok((select not enabled from vw_my_module_access where route_key='sales'),'enabling a window never grants missing data permission');
select set_config('test.actor','e2000000-0000-0000-0000-000000000005',false);
select pg_temp.ok((select enabled from vw_my_module_access where route_key='sales'),'multiple roles combine enabled windows');
select set_config('test.actor','e2000000-0000-0000-0000-000000000003',false);
select pg_temp.ok((select count(*)=0 from vw_my_module_access),'inactive profile cannot read module catalog');
select pg_temp.fails(format('select set_role_modules(%L,''[]'')',:'asst'),'Solo el Super','inactive profile cannot configure modules');
reset role;set role anon;
select pg_temp.fails('select * from vw_my_module_access','permission denied','anonymous cannot read access inventory');
select pg_temp.fails(format('select set_role_modules(%L,''[]'')',:'asst'),'permission denied','anonymous cannot configure modules');
reset role;
